import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const source = new URL("../../design-system/logisticspluscn-maritime/tokens.css", import.meta.url);
const targets = [
  new URL("../src/brand-tokens.css", import.meta.url),
  new URL("../../tracking-service/public/brand-tokens.css", import.meta.url)
];
const content =
  "/* Generated by frontend/scripts/sync-brand-tokens.mjs. Do not edit. */\n" +
  readFileSync(source, "utf8");
let valid = true;
for (const target of targets) {
  if (process.argv.includes("--check")) {
    let actual = "";
    try {
      actual = readFileSync(target, "utf8");
    } catch {}
    if (actual !== content) {
      console.error("Brand tokens out of sync: " + fileURLToPath(target));
      valid = false;
    }
  } else {
    writeFileSync(target, content);
  }
}
if (!valid) process.exitCode = 1;
else
  console.log(
    process.argv.includes("--check")
      ? "Brand tokens are synchronized."
      : "Brand token stylesheets generated."
  );
